const input = $input.first().json;
const payload = input.body ?? input;
const event = payload.event ?? payload;
const message = event.message ?? {};
const contact = event.contact ?? event.customer ?? {};
const eventType = event.eventType ?? event.type;
if (!['qualification.requested', 'message.received'].includes(eventType)) throw new Error('Esperado qualification.requested ou message.received');
if (!event.eventId || !event.companyId || !event.ticketId || !event.integrationId) throw new Error('Evento de qualificação sem eventId/companyId/ticketId/integrationId');
if (!event.customerId && !(contact.id ?? event.customer?.id)) throw new Error('Evento de qualificação sem customerId');
if (eventType === 'message.received' && !message.id) throw new Error('Resposta sem message.id');
if (typeof contact.phone !== 'string' || !contact.phone.trim()) throw new Error('Evento sem contact.phone');
return [{ json: {
  eventId: event.eventId,
  eventType,
  companyId: event.companyId,
  ticketId: event.ticketId,
  integrationId: event.integrationId,
  customerId: event.customerId ?? contact.id ?? event.customer?.id,
  customerName: contact.name ?? event.customer?.name ?? '',
  phone: contact.phone,
  messageId: message.id ?? null,
  replyText: eventType === 'message.received' ? String(message.text ?? message.body ?? '') : null,
} }];

const step = $input.first().json;
const original = $('Normalize qualification event').first().json;
if (step.error) throw new Error('Falha ao salvar a qualificação: ' + (step.error.message ?? 'erro da API'));
const prompts = {
  name: 'Para começar, qual é o seu nome?',
  company: (step.customerName ?? original.customerName)
    ? 'Obrigado, ' + String(step.customerName ?? original.customerName) + '. Qual é o nome da sua empresa?'
    : 'Obrigado por compartilhar. Qual é o nome da sua empresa?',
  interest: 'Qual produto ou serviço mais desperta o seu interesse?',
};
let text = '';
if (step.shouldSend === false) {
  text = '';
} else if (step.completed === true) {
  text = step.completionMessage ?? 'Obrigado pelas informações! Nossa equipe dará continuidade ao seu atendimento.';
} else if (prompts[step.nextField]) {
  text = prompts[step.nextField];
} else {
  throw new Error('Resposta da API inválida: nextField deve ser name, company ou interest; ou completed=true');
}
return [{ json: {
  ...original,
  shouldSend: Boolean(step.shouldSend ?? text),
  outgoingText: text,
  idempotencyKey: step.idempotencyKey ?? ('qualification:' + original.eventId),
} }];
